import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

sigmoid_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float sigmoidf_(float v) {
  return 1.0f / (1.0f + __expf(-v));
}

// Elementwise sigmoid kernel written with CuTe tensors/layouts.
// Grid-stride version: launch a fixed, machine-sized grid and let each
// block loop over many chunks. This removes the huge one-block-per-chunk
// grid that caused block-scheduling overhead and the achieved-vs-
// theoretical occupancy gap from workload imbalance, while keeping the
// unrolled, fully-coalesced float4 fast path with no bounds checks for
// whole in-bounds chunks. Only the final partial chunk in each block's
// stride takes the guarded path, so arbitrary numel stays in bounds.
template <int Vec>
__global__ void sigmoid_kernel_vec(const float* __restrict__ X,
                                   float* __restrict__ Y,
                                   int64_t numel_vec)
{
  constexpr int Unroll = 4;
  const float4* Xv = reinterpret_cast<const float4*>(X);
  float4* Yv = reinterpret_cast<float4*>(Y);
  Tensor mX = make_tensor(make_gmem_ptr(Xv), make_shape(numel_vec));
  Tensor mY = make_tensor(make_gmem_ptr(Yv), make_shape(numel_vec));
  const int64_t chunk = (int64_t)blockDim.x * Unroll;
  const int64_t gstride = (int64_t)gridDim.x * chunk;
  for (int64_t base = (int64_t)blockIdx.x * chunk; base < numel_vec; base += gstride) {
    const int64_t i0 = base + threadIdx.x;
    if (base + chunk <= numel_vec) {
      float4 v[Unroll];
#pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        v[u] = mX(i0 + (int64_t)u * blockDim.x);
      }
#pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        v[u].x = sigmoidf_(v[u].x);
        v[u].y = sigmoidf_(v[u].y);
        v[u].z = sigmoidf_(v[u].z);
        v[u].w = sigmoidf_(v[u].w);
      }
#pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        mY(i0 + (int64_t)u * blockDim.x) = v[u];
      }
    } else {
#pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        const int64_t i = i0 + (int64_t)u * blockDim.x;
        if (i < numel_vec) {
          float4 v = mX(i);
          v.x = sigmoidf_(v.x);
          v.y = sigmoidf_(v.y);
          v.z = sigmoidf_(v.z);
          v.w = sigmoidf_(v.w);
          mY(i) = v;
        }
      }
    }
  }
}

// Scalar tail kernel for leftover elements not covered by vector kernel.
__global__ void sigmoid_kernel_tail(const float* __restrict__ X,
                                    float* __restrict__ Y,
                                    int64_t offset,
                                    int64_t tail)
{
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  if (idx < tail) {
    Tensor mX = make_tensor(make_gmem_ptr(X + offset), make_shape(tail));
    Tensor mY = make_tensor(make_gmem_ptr(Y + offset), make_shape(tail));
    mY(idx) = sigmoidf_(mX(idx));
  }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t numel = x_c.numel();
  if (numel == 0) return y;

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  constexpr int Vec = 4;
  constexpr int Threads = 256;

  int64_t numel_vec = numel / Vec;
  int64_t tail = numel - numel_vec * Vec;

  bool handled_all_scalar = false;
  if (numel_vec > 0) {
    const bool vec_aligned =
        ((reinterpret_cast<size_t>(x_ptr) & 0xF) == 0) &&
        ((reinterpret_cast<size_t>(y_ptr) & 0xF) == 0);
    if (vec_aligned) {
      // Machine-sized persistent-style grid: launch only enough blocks to
      // fill every SM a few times over, then grid-stride inside the kernel.
      // This balances work across SMs and removes the block-scheduling cost
      // and imbalance of the previous 131k-block one-chunk-per-block grid,
      // closing the achieved-vs-theoretical occupancy gap.
      static int max_resident_blocks = -1;
      if (max_resident_blocks < 0) {
        int dev = 0;
        cudaGetDevice(&dev);
        int num_sms = 1;
        cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, dev);
        int blocks_per_sm = 1;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(
            &blocks_per_sm, sigmoid_kernel_vec<Vec>, Threads, 0);
        if (num_sms <= 0) num_sms = 1;
        if (blocks_per_sm <= 0) blocks_per_sm = 1;
        max_resident_blocks = num_sms * blocks_per_sm;
      }
      // Cap the grid at exactly one full wave of resident blocks so the
      // grid-stride kernel has no partial-wave tail: the previous
      // num_sms*8 cap exceeded the resident capacity (num_sms*6 at 34
      // regs/thread), leaving a partial wave of 256 blocks that the
      // profiler flagged as up to 50% of kernel runtime.
      const int64_t chunk = (int64_t)Threads * 4;
      int64_t blocks_needed = (numel_vec + chunk - 1) / chunk;
      int64_t blocks = blocks_needed;
      if (blocks > max_resident_blocks) blocks = max_resident_blocks;
      if (blocks < 1) blocks = 1;
      TORCH_CHECK(blocks <= 0x7fffffffLL, "sigmoid gridDim.x too large");
      sigmoid_kernel_vec<Vec><<<(unsigned)blocks, Threads, 0, stream>>>(
          x_ptr, y_ptr, numel_vec);
    } else {
      int64_t blocks = (numel + Threads - 1) / Threads;
      sigmoid_kernel_tail<<<(unsigned)blocks, Threads, 0, stream>>>(
          x_ptr, y_ptr, 0, numel);
      handled_all_scalar = true;
    }
  }
  if (!handled_all_scalar && tail > 0) {
    int64_t blocks = (tail + Threads - 1) / Threads;
    sigmoid_kernel_tail<<<(unsigned)blocks, Threads, 0, stream>>>(
        x_ptr, y_ptr, numel_vec * Vec, tail);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "sigmoid kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=sigmoid_cpp_decl,
    cuda_sources=sigmoid_cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Sigmoid activation implemented with a custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_forward(x)

